import java.util.List;

public class Main {
  public static void main(String[] args) {
      List<Registro> tabla = obtenerDatos();

      // En Java purgarías la lista mediante mutación:
      tabla.removeIf(r -> r.getDato() == null);

      System.out.println(tabla);
  }
}

// En Java tendrías que iterar la lista dos veces:
// 1. Calcular el promedio de 'Calorias' ignorando nulos.
// 2. Iterar nuevamente y asignar el promedio a los nulos.

double suma = 0;
int conteo = 0;
for (Registro r : tabla) {
    if (r.getCalorias() != null) {
       suma += r.getCalorias();
       conteo++;
    }
}
double prom = suma / conteo;
for (Registro r : tabla) {
    if (r.getCalorias() == null) r.setCalorias(prom);
}
